package cn.yuanxin.mvp.web.face;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * {@link FaceServiceClient#search} 严格形状校验与保守三态映射测试（契约 §2.3）。
 * 全部离线：本地 stub、合成字节，绝不联网。
 */
class FaceServiceClientSearchTest {

    private static final byte[] SYNTHETIC_IMAGE = "fake-search-bytes".getBytes(StandardCharsets.UTF_8);
    private static final String NAMESPACE = "openvela-mvp";

    private FaceServiceStub stub;
    private FaceServiceClient client;

    @BeforeEach
    void setUp() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
        client = new FaceServiceClient(new InsightFaceProperties(stub.baseUrl(), NAMESPACE,
                "FAKE-INTERNAL-TOKEN-DO-NOT-USE", null, 1500, 1500, 0.4), new ObjectMapper());
    }

    @AfterEach
    void tearDown() {
        stub.close();
    }

    private static String matched() {
        return "{\"decision\":\"matched\",\"subject_id\":\"subj-1\",\"similarity\":0.91,"
                + "\"ambiguous\":false,\"subject_count\":1,\"policy_version\":\"search-v1\","
                + "\"library_revision\":7,\"request_id\":\"r-matched\"}";
    }

    // ---------- 三态映射 ----------

    @Test
    @DisplayName("matched → MATCHED，携带 subjectRef/similarity/policyVersion/libraryRevision")
    void matchedMapsToMatched() {
        stub.search(200, matched());
        FaceSearchResult result = client.search("grant", SYNTHETIC_IMAGE);
        assertThat(result.decision()).isEqualTo(FaceSearchDecision.MATCHED);
        assertThat(result.matched()).isTrue();
        assertThat(result.subjectRef()).isEqualTo("subj-1");
        assertThat(result.similarity()).isEqualTo(0.91);
        assertThat(result.policyVersion()).isEqualTo("search-v1");
        assertThat(result.libraryRevision()).isEqualTo(7);
        assertThat(result.requestId()).isEqualTo("r-matched");
    }

    @Test
    @DisplayName("no_match → NO_MATCH，subjectRef/similarity 均为 null（构造器强制最小披露）")
    void noMatchMapsToNoMatch() {
        stub.search(200, "{\"decision\":\"no_match\",\"ambiguous\":false,\"subject_count\":0,"
                + "\"policy_version\":\"search-v1\",\"library_revision\":7,\"request_id\":\"r-nm\"}");
        FaceSearchResult result = client.search("grant", SYNTHETIC_IMAGE);
        assertThat(result.decision()).isEqualTo(FaceSearchDecision.NO_MATCH);
        assertThat(result.matched()).isFalse();
        assertThat(result.subjectRef()).isNull();
        assertThat(result.similarity()).isNull();
    }

    @Test
    @DisplayName("uncertain → UNCERTAIN，subjectRef/similarity 均为 null")
    void uncertainMapsToUncertain() {
        stub.search(200, "{\"decision\":\"uncertain\",\"ambiguous\":true,\"subject_count\":2,"
                + "\"policy_version\":\"search-v1\",\"library_revision\":7,\"request_id\":\"r-un\"}");
        FaceSearchResult result = client.search("grant", SYNTHETIC_IMAGE);
        assertThat(result.decision()).isEqualTo(FaceSearchDecision.UNCERTAIN);
        assertThat(result.subjectRef()).isNull();
        assertThat(result.similarity()).isNull();
    }

    @Test
    @DisplayName("wire：search 不传 top_k、不传阈值，且路径为 namespace 限定；内部 token 随请求发送")
    void searchWireShape() {
        stub.search(200, matched());
        client.search("grant", SYNTHETIC_IMAGE);
        FaceServiceStub.Request request = stub.last("POST", "/search");
        assertThat(request).isNotNull();
        assertThat(request.path()).isEqualTo("/v1/namespaces/openvela-mvp/search");
        assertThat(request.internalToken()).isEqualTo("FAKE-INTERNAL-TOKEN-DO-NOT-USE");
        String body = new String(request.body(), StandardCharsets.UTF_8);
        assertThat(body).contains("name=\"image\"").doesNotContain("top_k")
                .doesNotContain("threshold").doesNotContain("require_liveness");
    }

    // ---------- 严格形状校验（契约 §2.3；违规 ⇒ MALFORMED_RESPONSE，绝不返回 MATCHED/NO_MATCH） ----------

    @ParameterizedTest(name = "形状违规 #{index}: {0}")
    @DisplayName("判别力：任一必需键缺失/类型不符/未知 decision/非 matched 带 subject_id ⇒ MALFORMED")
    @ValueSource(strings = {
            // 缺 decision
            "{\"policy_version\":\"search-v1\",\"library_revision\":7,\"request_id\":\"r\"}",
            // 未知 decision
            "{\"decision\":\"maybe\",\"policy_version\":\"search-v1\",\"library_revision\":7,"
                    + "\"request_id\":\"r\"}",
            // matched 缺 subject_id
            "{\"decision\":\"matched\",\"similarity\":0.9,\"policy_version\":\"search-v1\","
                    + "\"library_revision\":7,\"request_id\":\"r\"}",
            // matched 缺 similarity
            "{\"decision\":\"matched\",\"subject_id\":\"subj-1\",\"policy_version\":\"search-v1\","
                    + "\"library_revision\":7,\"request_id\":\"r\"}",
            // matched similarity 非数值
            "{\"decision\":\"matched\",\"subject_id\":\"subj-1\",\"similarity\":\"0.9\","
                    + "\"policy_version\":\"search-v1\",\"library_revision\":7,\"request_id\":\"r\"}",
            // 非 matched 却带 subject_id（服务端契约禁止）
            "{\"decision\":\"no_match\",\"subject_id\":\"subj-1\",\"policy_version\":\"search-v1\","
                    + "\"library_revision\":7,\"request_id\":\"r\"}",
            // 非 matched 却带 subject_id=null（键出现即违约）
            "{\"decision\":\"uncertain\",\"subject_id\":null,\"policy_version\":\"search-v1\","
                    + "\"library_revision\":7,\"request_id\":\"r\"}",
            // 缺 policy_version
            "{\"decision\":\"no_match\",\"library_revision\":7,\"request_id\":\"r\"}",
            // 缺 library_revision
            "{\"decision\":\"no_match\",\"policy_version\":\"search-v1\",\"request_id\":\"r\"}",
            // 缺 request_id
            "{\"decision\":\"no_match\",\"policy_version\":\"search-v1\",\"library_revision\":7}",
            // 不可解析
            "not-json",
            // 非对象
            "[]"
    })
    void shapeViolationsFailClosed(String body) {
        stub.search(200, body);
        assertThatThrownBy(() -> client.search("grant", SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> {
                    FaceServiceException e = (FaceServiceException) thrown;
                    assertThat(e.error().code()).isEqualTo("MALFORMED_RESPONSE");
                    assertThat(e.kind()).isEqualTo(FaceServiceFailureKind.DEPENDENCY);
                });
    }

    @Test
    @DisplayName("超时 ⇒ FaceServiceException(DEPENDENCY)，绝不返回看似成功的默认值")
    void timeoutFailsClosed() {
        stub.delay(1600);
        FaceServiceClient slow = new FaceServiceClient(new InsightFaceProperties(stub.baseUrl(),
                NAMESPACE, "FAKE-INTERNAL-TOKEN-DO-NOT-USE", null, 1000, 1000, 0.4),
                new ObjectMapper());
        assertThatThrownBy(() -> slow.search("grant", SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> {
                    FaceServiceException e = (FaceServiceException) thrown;
                    assertThat(e.kind()).isEqualTo(FaceServiceFailureKind.DEPENDENCY);
                    assertThat(e.error().code()).isNotEqualTo("MATCHED");
                });
    }

    @Test
    @DisplayName("NAMESPACE_NOT_FOUND(404) ⇒ CAPABILITY（不降级成 no_match）")
    void namespaceNotFoundIsCapability() {
        stub.search(404, FaceServiceStub.errorBody("NAMESPACE_NOT_FOUND", false, "r-ns"));
        assertThatThrownBy(() -> client.search("grant", SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.CAPABILITY));
    }

    @Test
    @DisplayName("NO_FACE(400) ⇒ 抛异常（空白图绝不降级成 no_match）")
    void noFaceIsNotNoMatchDecision() {
        stub.search(400, FaceServiceStub.errorBody("NO_FACE", false, "r-nf"));
        assertThatThrownBy(() -> client.search("grant", SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).error().code())
                        .isEqualTo("NO_FACE"));
    }
}

package cn.yuanxin.mvp.web.face;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * {@link FaceServiceClient#register}/{@link FaceServiceClient#get}/{@link FaceServiceClient#delete}
 * 测试（契约 §4.9）。全部离线。
 *
 * <p><b>能力已实现且已测试，但尚无业务流程调用</b>：写 {@code members.face_subject_ref} 属跨包写域，
 * 待总协调裁定（见 {@code backend/handoffs/B-face-java.md}）。</p>
 */
class FaceServiceClientSubjectsTest {

    private static final byte[] SYNTHETIC_IMAGE = "fake-subject-bytes".getBytes(StandardCharsets.UTF_8);
    private static final String NAMESPACE = "openvela-mvp";
    private static final String SUBJECT = "subj-1";

    private FaceServiceStub stub;
    private FaceServiceClient client;

    @BeforeEach
    void setUp() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
        client = new FaceServiceClient(new InsightFaceProperties(stub.baseUrl(), NAMESPACE,
                "FAKE-INTERNAL-TOKEN-DO-NOT-USE", null, 1500, 1500, 0.4), new ObjectMapper());
    }

    @AfterEach
    void tearDown() {
        stub.close();
    }

    @Test
    @DisplayName("register 成功：解析 subjectRef/createdAt/libraryRevision，wire 带预确定 subject_id 与 on_exists=conflict")
    void registerSuccess() {
        FaceSubjectRegistration registration = client.register("enroll", SUBJECT, SYNTHETIC_IMAGE);
        assertThat(registration.subjectRef()).isEqualTo(SUBJECT);
        assertThat(registration.libraryRevision()).isEqualTo(4);
        assertThat(registration.createdAt()).isEqualTo("2026-01-01T00:00:00+00:00");
        assertThat(registration.requestId()).isEqualTo("req-register");

        FaceServiceStub.Request request = stub.last("POST", "/subjects");
        assertThat(request.path()).isEqualTo("/v1/namespaces/openvela-mvp/subjects");
        String body = new String(request.body(), StandardCharsets.UTF_8);
        assertThat(body).contains("name=\"image\"").contains("subj-1")
                .contains("name=\"on_exists\"").contains("conflict");
    }

    @Test
    @DisplayName("register：subject_id 回显不一致 ⇒ MALFORMED（绝不把别人的主体当成自己的）")
    void registerEchoMismatchFailsClosed() {
        stub.register(200, "{\"subject_id\":\"someone-else\",\"created_at\":\"2026-01-01T00:00:00+00:00\","
                + "\"library_revision\":4,\"request_id\":\"r\"}");
        assertThatThrownBy(() -> client.register("enroll", SUBJECT, SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).error().code())
                        .isEqualTo("MALFORMED_RESPONSE"));
    }

    @Test
    @DisplayName("register：SUBJECT_ALREADY_EXISTS(409) ⇒ 归类 CONFIGURATION")
    void subjectAlreadyExistsIsConfiguration() {
        stub.register(409, FaceServiceStub.errorBody("SUBJECT_ALREADY_EXISTS", false, "r-already"));
        assertThatThrownBy(() -> client.register("enroll", SUBJECT, SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.CONFIGURATION));
    }

    @Test
    @DisplayName("get 成功：返回主体视图")
    void getSuccess() {
        Optional<FaceSubjectView> found = client.get(SUBJECT);
        assertThat(found).isPresent();
        assertThat(found.get().subjectRef()).isEqualTo(SUBJECT);
        assertThat(found.get().libraryRevision()).isEqualTo(4);
    }

    @Test
    @DisplayName("get：404 SUBJECT_NOT_FOUND ⇒ Optional.empty()（不抛）")
    void getNotFoundReturnsEmpty() {
        stub.get(404, FaceServiceStub.errorBody("SUBJECT_NOT_FOUND", false, "r-404"));
        assertThat(client.get(SUBJECT)).isEmpty();
    }

    @Test
    @DisplayName("get：404 NAMESPACE_NOT_FOUND ⇒ Optional.empty()（不存在的 namespace 内也无主体）")
    void getNamespaceNotFoundReturnsEmpty() {
        stub.get(404, FaceServiceStub.errorBody("NAMESPACE_NOT_FOUND", false, "r-ns"));
        assertThat(client.get(SUBJECT)).isEmpty();
    }

    @Test
    @DisplayName("get：503 ⇒ 照常抛 DEPENDENCY（绝不把依赖故障当'不存在'）")
    void getDependencyFailureThrows() {
        stub.get(503, FaceServiceStub.errorBody("MODEL_UNAVAILABLE", true, "r-dep"));
        assertThatThrownBy(() -> client.get(SUBJECT))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.DEPENDENCY));
    }

    @Test
    @DisplayName("delete 成功：deleted=true + libraryRevision")
    void deleteSuccess() {
        FaceSubjectDeletion deletion = client.delete(SUBJECT);
        assertThat(deletion.deleted()).isTrue();
        assertThat(deletion.libraryRevision()).isEqualTo(5);
        assertThat(deletion.requestId()).isEqualTo("req-delete");
    }

    @Test
    @DisplayName("delete 重复删除幂等：第二次 404 ⇒ deleted=false + 未知修订，不抛")
    void deleteRepeatIsIdempotent() {
        FaceSubjectDeletion first = client.delete(SUBJECT);
        assertThat(first.deleted()).isTrue();

        stub.delete(404, FaceServiceStub.errorBody("SUBJECT_NOT_FOUND", false, "r-again"));
        FaceSubjectDeletion second = client.delete(SUBJECT);
        assertThat(second.deleted()).isFalse();
        assertThat(second.libraryRevision())
                .isEqualTo(FaceSubjectDeletion.UNKNOWN_LIBRARY_REVISION);
        assertThat(second.requestId()).isEqualTo("r-again");
    }

    @Test
    @DisplayName("delete：5xx ⇒ 照常抛 DEPENDENCY（绝不误报'已删除'）")
    void deleteDependencyFailureThrows() {
        stub.delete(503, FaceServiceStub.errorBody("MODEL_UNAVAILABLE", true, "r-dep"));
        assertThatThrownBy(() -> client.delete(SUBJECT))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.DEPENDENCY));
    }

    @Test
    @DisplayName("delete：deleted 非 boolean ⇒ MALFORMED")
    void deleteWrongShapeFailsClosed() {
        stub.delete(200, "{\"deleted\":\"true\",\"library_revision\":5,\"request_id\":\"r\"}");
        assertThatThrownBy(() -> client.delete(SUBJECT))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).error().code())
                        .isEqualTo("MALFORMED_RESPONSE"));
    }
}

package cn.yuanxin.mvp.web.face;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** {@link FaceServiceClient#quality} 严格质量块校验测试（契约 §2.2）。全部离线。 */
class FaceServiceClientQualityTest {

    private static final byte[] SYNTHETIC_IMAGE = "fake-quality-bytes".getBytes(StandardCharsets.UTF_8);

    private FaceServiceStub stub;
    private FaceServiceClient client;

    @BeforeEach
    void setUp() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
        client = new FaceServiceClient(new InsightFaceProperties(stub.baseUrl(), "openvela-mvp",
                "FAKE-INTERNAL-TOKEN-DO-NOT-USE", null, 1500, 1500, 0.4), new ObjectMapper());
    }

    @AfterEach
    void tearDown() {
        stub.close();
    }

    @Test
    @DisplayName("quality 成功：face_count/min_acceptable/liveness.supported（如实）")
    void qualityParsed() {
        FaceQualityView view = client.quality("grant", SYNTHETIC_IMAGE);
        assertThat(view.faceCount()).isEqualTo(1);
        assertThat(view.minAcceptable()).isTrue();
        assertThat(view.reasons()).isEmpty();
        assertThat(view.livenessSupported()).isFalse();
        assertThat(view.requestId()).isEqualTo("req-quality");
    }

    @Test
    @DisplayName("quality：取 largest_face 的质量判定（不是第一张脸）")
    void qualityUsesLargestFace() {
        stub.quality(200, "{\"face_count\":2,\"faces\":["
                + "{\"quality\":{\"min_acceptable\":true},\"largest_face\":false},"
                + "{\"quality\":{\"min_acceptable\":false},\"largest_face\":true}],"
                + "\"liveness\":{\"supported\":false},\"request_id\":\"r-two\"}");
        FaceQualityView view = client.quality("grant", SYNTHETIC_IMAGE);
        assertThat(view.faceCount()).isEqualTo(2);
        assertThat(view.minAcceptable()).isFalse();
    }

    @ParameterizedTest(name = "质量形状违规 #{index}")
    @DisplayName("quality 形状违规 ⇒ MALFORMED_RESPONSE（绝不默认成合格）")
    @ValueSource(strings = {
            "{\"faces\":[{\"quality\":{\"min_acceptable\":true},\"largest_face\":true}],"
                    + "\"liveness\":{\"supported\":false}}",
            "{\"face_count\":1,\"faces\":[],\"liveness\":{\"supported\":false}}",
            "{\"face_count\":1,\"liveness\":{\"supported\":false}}",
            "{\"face_count\":1,\"faces\":[{\"largest_face\":true}],"
                    + "\"liveness\":{\"supported\":false}}",
            "{\"face_count\":-1,\"faces\":[{\"quality\":{\"min_acceptable\":true},\"largest_face\":true}],"
                    + "\"liveness\":{\"supported\":false}}",
            "{\"face_count\":1,\"faces\":[{\"quality\":{\"min_acceptable\":\"yes\"},\"largest_face\":true}],"
                    + "\"liveness\":{\"supported\":false}}",
            "{\"face_count\":1,\"faces\":[{\"quality\":{\"min_acceptable\":true},\"largest_face\":true}]}"
    })
    void qualityShapeViolationsFailClosed(String body) {
        stub.quality(200, body);
        assertThatThrownBy(() -> client.quality("grant", SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).error().code())
                        .isEqualTo("MALFORMED_RESPONSE"));
    }

    @Test
    @DisplayName("QUALITY_INSUFFICIENT(422) ⇒ 抛异常并保留服务码（不静默成合格）")
    void qualityInsufficientThrows() {
        stub.quality(422, FaceServiceStub.errorBody("QUALITY_INSUFFICIENT", false, "r-q"));
        assertThatThrownBy(() -> client.quality("grant", SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
