package cn.yuanxin.mvp.web.face;

import cn.yuanxin.mvp.web.auth.FaceClassification;
import cn.yuanxin.mvp.web.identity.ResolvedFaceIdentity;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * {@link InsightFaceIdentityResolver} 测试（契约 §4.7）。全部离线。
 *
 * <p>刻意覆盖"两次搜索"代价：{@code classify} 一次 + {@code resolve} 一次；
 * 本测试断言 resolver 自身只发起<b>一次</b>搜索，且非 MATCHED 分类<b>零</b>远端调用。</p>
 */
class InsightFaceIdentityResolverTest {

    private static final byte[] SYNTHETIC_IMAGE = "fake-resolve-bytes".getBytes(StandardCharsets.UTF_8);

    private FaceServiceStub stub;
    private InsightFaceIdentityResolver resolver;

    @BeforeEach
    void setUp() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
        InsightFaceProperties props = new InsightFaceProperties(stub.baseUrl(), "openvela-mvp",
                "FAKE-INTERNAL-TOKEN-DO-NOT-USE", null, 1500, 1500, null);
        resolver = new InsightFaceIdentityResolver(new FaceServiceClient(props, new ObjectMapper()),
                props);
    }

    @AfterEach
    void tearDown() {
        stub.close();
    }

    @Test
    @DisplayName("classification != MATCHED ⇒ empty，且零远端调用（保守，不浪费推理）")
    void nonMatchedIsEmptyWithoutRemoteCall() {
        for (FaceClassification classification : new FaceClassification[]{
                FaceClassification.UNCERTAIN, FaceClassification.QUALITY_REJECTED,
                FaceClassification.DEPENDENCY_FAILED, FaceClassification.RELIABLE_NEW}) {
            assertThat(resolver.resolve(SYNTHETIC_IMAGE, classification)).isEmpty();
        }
        assertThat(stub.requests()).isEmpty();
    }

    @Test
    @DisplayName("MATCHED + 搜索命中 ⇒ ResolvedFaceIdentity(namespace, subjectRef)；resolver 自身只搜一次")
    void matchedResolvesIdentity() {
        stub.search(200, "{\"decision\":\"matched\",\"subject_id\":\"subj-1\",\"similarity\":0.9,"
                + "\"policy_version\":\"search-v1\",\"library_revision\":3,\"request_id\":\"r\"}");
        Optional<ResolvedFaceIdentity> identity =
                resolver.resolve(SYNTHETIC_IMAGE, FaceClassification.MATCHED);
        assertThat(identity).isPresent();
        assertThat(identity.get().identityNamespace()).isEqualTo("openvela-mvp");
        assertThat(identity.get().faceSubjectRef()).isEqualTo("subj-1");
        assertThat(resolver.identityNamespace()).isEqualTo("openvela-mvp");
        // 第二次搜索的代价：resolver 自身恰好一次搜索（classify 那次由 provider 完成）。
        assertThat(stub.count("POST", "/search")).isEqualTo(1);
    }

    @Test
    @DisplayName("MATCHED 但第二次搜索 no_match ⇒ empty（不一致即保守拒绝，绝不放行）")
    void inconsistentNoMatchIsEmpty() {
        stub.search(200, "{\"decision\":\"no_match\",\"policy_version\":\"search-v1\","
                + "\"library_revision\":3,\"request_id\":\"r\"}");
        assertThat(resolver.resolve(SYNTHETIC_IMAGE, FaceClassification.MATCHED)).isEmpty();
    }

    @Test
    @DisplayName("MATCHED 但第二次搜索 uncertain ⇒ empty（歧义绝不放行）")
    void inconsistentUncertainIsEmpty() {
        stub.search(200, "{\"decision\":\"uncertain\",\"policy_version\":\"search-v1\","
                + "\"library_revision\":3,\"request_id\":\"r\"}");
        assertThat(resolver.resolve(SYNTHETIC_IMAGE, FaceClassification.MATCHED)).isEmpty();
    }

    @Test
    @DisplayName("如实记录：第二次搜索依赖故障按端口契约抛出（调用方负责映射 503）")
    void dependencyFailurePropagates() {
        stub.search(503, FaceServiceStub.errorBody("MODEL_UNAVAILABLE", true, "r-dep"));
        assertThatThrownBy(() -> resolver.resolve(SYNTHETIC_IMAGE, FaceClassification.MATCHED))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.DEPENDENCY));
    }
}

package cn.yuanxin.mvp.web.face;

import cn.yuanxin.mvp.web.care.CareFaceVerifier;
import cn.yuanxin.mvp.web.identity.ResolvedFaceIdentity;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * <b>类型分离的编译期证据</b>（契约 §4.4）：护理路径只可能消费
 * {@link LivenessVerifiedMatch}，照片比对结果 {@link PhotoComparisonMatch} 无法替代。
 *
 * <p>两种语义在类型层面分离，<b>混用会编译失败</b>——本测试用反射防止将来有人把两者
 * 合并成同一类型（例如让 {@code LivenessVerifiedMatch} 继承 {@code PhotoComparisonMatch}，
 * 或在 {@code FaceIdentityPort} 上把两个方法合并）。
 *
 * <p>说明：护理接口 {@code CareFaceVerifier.verifyOneToOne} 返回的是 {@code Outcome} 枚举
 * （C 包既定契约，不改），因此"护理只接受 LivenessVerifiedMatch"体现为
 * {@link InsightFaceCareVerifier} 依赖 {@link FaceIdentityPort} 且<b>绝不</b>声明
 * {@link PhotoComparisonMatch} 字段；其唯一可用的匹配类型来自
 * {@link FaceIdentityPort#verifyWithLiveness}。</p>
 */
class CareFaceVerifierTypeSeparationTest {

    private static final List<String> INVALIDATION =
            List.of("两个类型可互相赋值", "护理 verifier 依赖 PhotoComparisonMatch", "端口方法返回类型合并");

    @Test
    @DisplayName("端口两方法返回类型不同：verifyWithLiveness→LivenessVerifiedMatch，verifyPhotoOnly→PhotoComparisonMatch")
    void portMethodsReturnDistinctTypes() throws Exception {
        Method liveness = FaceIdentityPort.class.getMethod("verifyWithLiveness",
                String.class, String.class, byte[].class);
        Method photo = FaceIdentityPort.class.getMethod("verifyPhotoOnly",
                String.class, String.class, byte[].class);

        assertThat(liveness.getReturnType()).isEqualTo(LivenessVerifiedMatch.class);
        assertThat(photo.getReturnType()).isEqualTo(PhotoComparisonMatch.class);
        assertThat(liveness.getReturnType()).isNotEqualTo(photo.getReturnType());
    }

    @Test
    @DisplayName("两个匹配类型无子类型关系（混用必编译失败，不是冗余）")
    void matchTypesAreNotAssignableToEachOther() {
        assertThat(PhotoComparisonMatch.class.isAssignableFrom(LivenessVerifiedMatch.class)).isFalse();
        assertThat(LivenessVerifiedMatch.class.isAssignableFrom(PhotoComparisonMatch.class)).isFalse();
        assertThat(PhotoComparisonMatch.class).isNotSameAs(LivenessVerifiedMatch.class);
    }

    @Test
    @DisplayName("护理 verifier 依赖 FaceIdentityPort 且绝不声明 PhotoComparisonMatch")
    void careVerifierNeverDependsOnPhotoComparison() {
        List<Class<?>> fieldTypes = Arrays.stream(InsightFaceCareVerifier.class.getDeclaredFields())
                .map(Field::getType)
                .toList();
        assertThat(fieldTypes).contains(FaceIdentityPort.class).doesNotContain(PhotoComparisonMatch.class);

        List<Class<?>> ctorParamTypes = Arrays.stream(InsightFaceCareVerifier.class.getConstructors())
                .flatMap(ctor -> Arrays.stream(ctor.getParameterTypes()))
                .toList();
        assertThat(ctorParamTypes).contains(FaceIdentityPort.class)
                .doesNotContain(PhotoComparisonMatch.class);
    }

    @Test
    @DisplayName("护理接口返回 Outcome（非匹配类型），证据：不会出现把两种匹配混用的签名")
    void careVerifierOutcomeIsNotAMatchType() throws Exception {
        Method verify = CareFaceVerifier.class.getMethod("verifyOneToOne",
                String.class, java.util.UUID.class, byte[].class);
        assertThat(verify.getReturnType()).isEqualTo(CareFaceVerifier.Outcome.class);
        assertThat(verify.getReturnType()).isNotEqualTo(LivenessVerifiedMatch.class);
        assertThat(verify.getReturnType()).isNotEqualTo(PhotoComparisonMatch.class);
        // 判别力说明：上面任何一条失败，就意味着两种语义被合并（本测试注释中列出的失效条件）。
        assertThat(INVALIDATION).isNotEmpty();
    }

    @Test
    @DisplayName("身份解析器依赖端口而非直接依赖 HTTP 客户端类型（供应商无关）")
    void resolverDependsOnPort() {
        List<Class<?>> fieldTypes = Arrays.stream(InsightFaceIdentityResolver.class.getDeclaredFields())
                .map(Field::getType)
                .toList();
        assertThat(fieldTypes).contains(FaceIdentityPort.class);
        // 端口类型仍然存在且方法可用（编译期契约）。
        assertThat(FaceIdentityPort.class.getMethods())
                .anySatisfy(m -> assertThat(m.getName()).isEqualTo("search"));
        assertThat(ResolvedFaceIdentity.class.getRecordComponents()).hasSize(2);
    }
}

