package cn.yuanxin.mvp.web.identity;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;

import java.util.Map;

/**
 * <b>可区分的围栏异常</b>：身份登记的业务事务内 {@code SELECT ... FOR UPDATE} 重读 T05 后发现
 * 五条围栏（{@code B-identity-result-contract.md} §6）任一不满足。
 *
 * <p>与依赖故障<b>必须可区分</b>：依赖故障是 503 {@code DEPENDENCY_UNAVAILABLE}（可重试，
 * 由 {@code IdentityEnrollmentService} 抛出）；本异常是 409 {@code TASK_REPLACED}（不可重试，
 * 含义是"任务输入已被补拍/重跑替换，不能把旧登记结果归给新照片"）。调用方据 {@code instanceof}
 * 或 {@code reason} 区分处置，绝不把两者混为一谈。</p>
 *
 * <p>{@code reason} 只是围栏字段名（{@code processing_revision}/{@code current_photo_version}/
 * {@code status}/{@code candidate_entity_id}/{@code phase}/{@code assessment_not_found}），
 * <b>不含</b> {@code faceSubjectRef}/{@code memberId}/namespace/media id/图片字节等敏感值。</p>
 */
public class IdentityEnrollmentFenceException extends ApiException {

    private final String reason;

    public IdentityEnrollmentFenceException(String reason) {
        super(ErrorCode.TASK_REPLACED, ErrorCode.TASK_REPLACED.defaultStatus().value(),
                ErrorCode.TASK_REPLACED.defaultRetryable(),
                "identity enrollment input no longer current (fence rejected)",
                Map.of("reason", reason == null ? "unknown" : reason), null);
        this.reason = reason == null ? "unknown" : reason;
    }

    /** 失败的围栏字段名（非敏感）。 */
    public String reason() {
        return reason;
    }
}

package cn.yuanxin.mvp.web.identity;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.face.FaceIdentityPort;
import cn.yuanxin.mvp.web.face.FaceServiceException;
import cn.yuanxin.mvp.web.face.FaceServiceFailureKind;
import cn.yuanxin.mvp.web.face.FaceSubjectView;
import cn.yuanxin.mvp.web.media.MediaObject;
import cn.yuanxin.mvp.web.media.MediaService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;

import java.io.IOException;
import java.io.InputStream;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;

/**
 * {@link IdentityEnrollmentService} 的 JDBC 生产端实现（B 自有）。
 *
 * <p><b>数据面</b>：只写 T01 {@code members}（{@code identity_namespace}/{@code face_subject_ref}/
 * {@code identity_summary}/{@code created_from_assessment_id}/{@code status}）。<b>绝不</b>写
 * T05 {@code skin_assessments.identity_result} 或 {@code member_id}（Worker 独占列），
 * T05 仅以 {@code SELECT ... FOR UPDATE} <b>只读</b>做围栏。依据
 * {@code backend/handoffs/B-identity-result-contract.md} §1/§5/§6。</p>
 *
 * <p><b>五条围栏（合同 §6，业务事务内、持锁时）</b>：{@code processing_revision}、
 * {@code current_photo_version}、{@code status='analyzing'}、
 * {@code identity_result->>'candidate_entity_id'} 与派生值一致、
 * {@code identity_result->>'phase' IN ('enroll_pending','enroll_started')}。任一不符 ⇒ 不写成员行、
 * 抛 {@link IdentityEnrollmentFenceException}（409 {@code TASK_REPLACED}，与依赖故障可区分）。
 * 第 4/5 条读的是 T05 {@code identity_result}（D 独占列）——<b>只读校验、绝不写</b>。</p>
 *
 * <p><b>远端调用在事务外</b>（合同 §8.4）：先 {@code port.get(faceSubjectRef)} 对账，命中即
 * {@link IdentityEnrollmentPhase#ENROLLED_RECONCILED} 且<b>不</b>重复 register；未命中才
 * {@code port.register("enroll", ref, referenceImage)} ⇒ {@link IdentityEnrollmentPhase#ENROLLED}。
 * <b>参考图裁定为 {@code front}（正脸）</b>：人脸服务 {@code POST /v1/namespaces/{ns}/subjects}
 * 只接受单张 image，正脸是登记的主参考视角；{@code left}/{@code right} 仍写入
 * {@code identity_summary.reference_media}（D 的 {@code media_cleanup} 依赖这三个 id）。</p>
 *
 * <p><b>幂等与对账</b>：{@code faceSubjectRef} 由
 * {@link IdentityEnrollmentCommand#faceSubjectRef()} 确定性派生；本地插入用
 * {@code INSERT ... ON CONFLICT ... DO NOTHING} + 回查（由 {@code uq_members_identity} 兜底），
 * {@code memberRowInserted} 如实反映是否真的插入。{@code identity_summary} 与成员行同事务提交
 * ⇒ 无"行在而摘要缺"的中间态。</p>
 *
 * <p><b>可见性时点（合同 §9）</b>：结果只在成员行提交后返回；远端已登记但本地未能提交时抛异常
 * 供调用方重试对账，<b>绝不</b>返回查不到的 memberId，<b>绝不</b>自动删除远端 subject。</p>
 *
 * <p><b>脱敏</b>：日志与异常消息不含 {@code faceSubjectRef}、{@code memberId}、namespace 取值、
 * media id、图片字节或凭据；围栏异常只暴露围栏字段名。</p>
 */
public class JdbcIdentityEnrollmentService implements IdentityEnrollmentService {

    private static final Logger log = LoggerFactory.getLogger(JdbcIdentityEnrollmentService.class);

    /** 发送给人脸服务的 purpose（仅审计分类，非身份信息；服务端不据此判定）。 */
    static final String ENROLL_PURPOSE = "enroll";

    private static final String INSERT_MEMBER = "INSERT INTO members"
            + " (id, identity_namespace, face_subject_ref, profile, identity_summary,"
            + " created_from_assessment_id, status)"
            + " VALUES (?, ?, ?, '{}'::jsonb, CAST(? AS jsonb), ?, 'active')"
            + " ON CONFLICT (identity_namespace, face_subject_ref)"
            + " WHERE identity_namespace IS NOT NULL AND face_subject_ref IS NOT NULL"
            + " DO NOTHING"
            + " RETURNING id";

    private static final String SELECT_MEMBER = "SELECT id, status FROM members"
            + " WHERE identity_namespace = ? AND face_subject_ref = ?";

    private static final String SELECT_ASSESSMENT_FOR_UPDATE = "SELECT status,"
            + " current_photo_version, processing_revision,"
            + " identity_result ->> 'candidate_entity_id' AS candidate_entity_id,"
            + " identity_result ->> 'phase' AS phase"
            + " FROM skin_assessments WHERE id = ? FOR UPDATE";

    private final JdbcTemplate jdbc;
    private final TransactionTemplate txTemplate;
    private final MediaService mediaService;
    private final FaceIdentityPort port;

    public JdbcIdentityEnrollmentService(JdbcTemplate jdbc, TransactionTemplate txTemplate,
                                         MediaService mediaService, FaceIdentityPort port) {
        this.jdbc = jdbc;
        this.txTemplate = txTemplate;
        this.mediaService = mediaService;
        this.port = port;
    }

    @Override
    public IdentityEnrollmentResult enroll(IdentityEnrollmentCommand command) {
        if (command == null) {
            throw new IllegalArgumentException("command must not be null");
        }
        String faceSubjectRef = command.faceSubjectRef();
        requireDeterministicDerivation(command);
        requireMatchingNamespace(command);

        // 远端调用严格在业务事务之外：参考图字节先经既有存储读取路径取得（fail-closed）。
        byte[] referenceImage = readReferenceImage(command.referenceMediaFront());
        RemoteEnrollment remote = resolveRemote(command, faceSubjectRef, referenceImage);

        return Objects.requireNonNull(txTemplate.execute(
                status -> commitMember(command, faceSubjectRef, remote)));
    }

    // ------------------------------------------------------------------ 输入校验

    /**
     * {@code correlationId}/{@code providerRequestId} 必须是合同 §5 的确定性派生值；
     * 传入自定义值会让跨重试对账失效 ⇒ 拒绝（400 {@code INVALID_INPUT}）。
     */
    private void requireDeterministicDerivation(IdentityEnrollmentCommand command) {
        String expectedCorrelation =
                IdentityResultContract.enrollCorrelationId(command.identityNamespace(),
                        command.assessmentId());
        if (!expectedCorrelation.equals(command.correlationId())) {
            throw new ApiException(ErrorCode.INVALID_INPUT,
                    "identity enrollment correlationId is not the deterministic derived value");
        }
        String expectedRequest = IdentityResultContract.providerRequestId(expectedCorrelation);
        if (!expectedRequest.equals(command.providerRequestId())) {
            throw new ApiException(ErrorCode.INVALID_INPUT,
                    "identity enrollment providerRequestId is not the deterministic derived value");
        }
    }

    /** 命令 namespace 必须与端口当前配置一致，否则远端会落到错误命名空间（不可重试配置错误）。 */
    private void requireMatchingNamespace(IdentityEnrollmentCommand command) {
        String portNamespace = port.identityNamespace();
        if (portNamespace == null || !portNamespace.equals(command.identityNamespace())) {
            throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE, 503, false,
                    "identity enrollment namespace configuration mismatch", null, Map.of());
        }
    }

    /** 参考图（front）必须已 available；任何不可读都 fail-closed，绝不用占位字节。 */
    private byte[] readReferenceImage(String rawMediaId) {
        UUID mediaId;
        try {
            mediaId = UUID.fromString(rawMediaId);
        } catch (IllegalArgumentException invalidId) {
            throw new ApiException(ErrorCode.INVALID_INPUT, "reference media id is not a valid id");
        }
        MediaObject media = mediaService.load(mediaId);
        if (media == null || !"available".equals(media.state())) {
            throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE,
                    "reference face image is unavailable");
        }
        InputStream in = mediaService.openContent(media);
        if (in == null) {
            throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE,
                    "reference face image is unavailable");
        }
        try (in) {
            return in.readAllBytes();
        } catch (IOException readFailure) {
            throw new ApiException(ErrorCode.DEPENDENCY_TIMEOUT, "reference face image read failed");
        }
    }

    // ------------------------------------------------------------------ 远端（事务外）

    private RemoteEnrollment resolveRemote(IdentityEnrollmentCommand command, String faceSubjectRef,
                                           byte[] referenceImage) {
        try {
            Optional<FaceSubjectView> existing = port.get(faceSubjectRef);
            if (existing.isPresent()) {
                return RemoteEnrollment.reconciled(faceSubjectRef);
            }
            port.register(ENROLL_PURPOSE, faceSubjectRef, referenceImage);
            return RemoteEnrollment.enrolled();
        } catch (FaceServiceException failure) {
            // get→register 之间的并发登记竞态：确定性 ref 已存在 ⇒ 认领既有登记，不重复登记、不报错。
            if ("SUBJECT_ALREADY_EXISTS".equals(failure.error().safeCode())) {
                return RemoteEnrollment.reconciled(faceSubjectRef);
            }
            if (failure.kind() == FaceServiceFailureKind.CONFIGURATION) {
                throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE, 503, false,
                        "identity enrollment dependency is misconfigured", null, Map.of());
            }
            throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE,
                    "identity enrollment dependency unavailable");
        }
    }

    // ------------------------------------------------------------------ 本地（业务事务内）

    private IdentityEnrollmentResult commitMember(IdentityEnrollmentCommand command,
                                                  String faceSubjectRef, RemoteEnrollment remote) {
        requireFence(command, faceSubjectRef);

        Instant registeredAt = Instant.now();
        UUID candidateMemberId = UUID.randomUUID();
        IdentityEnrollmentResult provisional = new IdentityEnrollmentResult(candidateMemberId,
                command.identityNamespace(), faceSubjectRef, remote.phase(), remote.classification(),
                remote.matchedExistingSubjectRef(), registeredAt, true);
        String identitySummary =
                IdentityResultContract.buildIdentitySummary(command, provisional).toString();

        List<UUID> inserted = jdbc.query(INSERT_MEMBER,
                (rs, i) -> rs.getObject("id", UUID.class),
                candidateMemberId, command.identityNamespace(), faceSubjectRef, identitySummary,
                command.assessmentId());

        boolean memberRowInserted = !inserted.isEmpty();
        UUID memberId;
        if (memberRowInserted) {
            memberId = inserted.get(0);
        } else {
            // uq_members_identity 冲突 ⇒ 幂等重试命中既有行（不覆盖既有摘要）。
            List<MemberLookup> existing = jdbc.query(SELECT_MEMBER,
                    (rs, i) -> new MemberLookup(rs.getObject("id", UUID.class),
                            rs.getString("status")),
                    command.identityNamespace(), faceSubjectRef);
            if (existing.isEmpty()) {
                throw new IllegalStateException(
                        "members conflict resolved but no existing row is visible");
            }
            MemberLookup row = existing.get(0);
            if (!"active".equals(row.status())) {
                // 可见性不变量：结果必须能被 status='active' 的只读定位立刻查到。
                throw new ApiException(ErrorCode.DEPENDENCY_UNAVAILABLE, 503, false,
                        "identity enrollment cannot produce a visible active member", null, Map.of());
            }
            memberId = row.id();
        }

        log.info("identity enrollment committed memberRowInserted={} phase={}",
                memberRowInserted, remote.phase().wireValue());
        return new IdentityEnrollmentResult(memberId, command.identityNamespace(), faceSubjectRef,
                remote.phase(), remote.classification(), remote.matchedExistingSubjectRef(),
                registeredAt, memberRowInserted);
    }

    /** 五条围栏全查；任一不符 ⇒ 抛 {@link IdentityEnrollmentFenceException}（回滚，不写成员行）。 */
    private void requireFence(IdentityEnrollmentCommand command, String faceSubjectRef) {
        List<FenceRow> rows = jdbc.query(SELECT_ASSESSMENT_FOR_UPDATE,
                (rs, i) -> new FenceRow(rs.getString("status"),
                        rs.getLong("current_photo_version"),
                        rs.getLong("processing_revision"),
                        rs.getString("candidate_entity_id"),
                        rs.getString("phase")),
                command.assessmentId());
        if (rows.isEmpty()) {
            throw new IdentityEnrollmentFenceException("assessment_not_found");
        }
        FenceRow row = rows.get(0);
        if (row.processingRevision() != command.processingRevision()) {
            throw new IdentityEnrollmentFenceException("processing_revision");
        }
        if (row.photoVersion() != command.photoVersion()) {
            throw new IdentityEnrollmentFenceException("current_photo_version");
        }
        if (!"analyzing".equals(row.status())) {
            throw new IdentityEnrollmentFenceException("status");
        }
        if (!faceSubjectRef.equals(row.candidateEntityId())) {
            throw new IdentityEnrollmentFenceException("candidate_entity_id");
        }
        if (!"enroll_pending".equals(row.phase()) && !"enroll_started".equals(row.phase())) {
            throw new IdentityEnrollmentFenceException("phase");
        }
    }

    private record FenceRow(String status, long photoVersion, long processingRevision,
                            String candidateEntityId, String phase) {
    }

    private record MemberLookup(UUID id, String status) {
    }

    /** 远端登记结果（事务外确定，事务内只用于构造摘要与结果）。 */
    private record RemoteEnrollment(IdentityEnrollmentPhase phase, String classification,
                                    String matchedExistingSubjectRef) {

        static RemoteEnrollment enrolled() {
            return new RemoteEnrollment(IdentityEnrollmentPhase.ENROLLED,
                    IdentityResultContract.CLASSIFICATION_RELIABLE_NEW_CANDIDATE_ENROLLED, null);
        }

        /** 远端此前已登记（对账命中/并发登记冲突）：复用既有主体，matched_subject_ref = faceSubjectRef。 */
        static RemoteEnrollment reconciled(String faceSubjectRef) {
            return new RemoteEnrollment(IdentityEnrollmentPhase.ENROLLED_RECONCILED,
                    IdentityResultContract.CLASSIFICATION_MATCHED_EXISTING, faceSubjectRef);
        }
    }
}

