/**
 * 身份登记生产端（{@link JdbcIdentityEnrollmentService}）的装配（B 自有，不改 A/C 域配置类）。
 *
 * <p>装配条件与既有 {@code InsightFaceCareVerifier} 的生产处置一致（三重要求）：
 * <ul>
 *   <li>{@code app.face.provider=insightface}——真实人脸端口存在；</li>
 *   <li>{@link FaceProviderEnabledCondition}——{@code app.providers.mode} 未被显式
 *       {@code disabled} 关闭（能力显式关闭优先）；</li>
 *   <li>{@link NonProductionCondition}——<b>非生产信号</b>。生产信号下不装配真实实现，
 *       避免在真实身份写入链路未经生产放行前暴露。</li>
 * </ul>
 *
 * <p>本轮<b>不接线任何业务流程</b>（触发点位于 D 的写域，见
 * {@code backend/handoffs/B-identity-result-contract.md} §9）；本配置只把"能力"装配成 bean，
 * 供裁定后的调用方注入。</p>
 */
@Configuration
@ConditionalOnProperty(name = "app.face.provider", havingValue = "insightface")
@Conditional(FaceProviderEnabledCondition.class)
@Conditional(NonProductionCondition.class)
public class IdentityEnrollmentConfig {

    @Bean
    public IdentityEnrollmentService identityEnrollmentService(JdbcTemplate jdbc,
                                                              TransactionTemplate transactionTemplate,
                                                              MediaService mediaService,
                                                              FaceIdentityPort faceIdentityPort) {
        return new JdbcIdentityEnrollmentService(jdbc, transactionTemplate, mediaService,
                faceIdentityPort);
    }
}

