package cn.yuanxin.mvp.web.identity;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import cn.yuanxin.mvp.web.config.AppProperties;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.face.FaceServiceClient;
import cn.yuanxin.mvp.web.face.FaceServiceStub;
import cn.yuanxin.mvp.web.face.InsightFaceProperties;
import cn.yuanxin.mvp.web.media.MediaService;
import cn.yuanxin.mvp.web.media.StoragePort;
import cn.yuanxin.mvp.web.support.AbstractWebIT;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DataAccessResourceFailureException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.transaction.support.TransactionTemplate;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link JdbcIdentityEnrollmentService} 生产端实现 vs. 冻结合同
 * （{@code backend/handoffs/B-identity-result-contract.md}）的集成测试。
 *
 * <p>真实 PG（55435 + Flyway）+ 本地 {@link FaceServiceStub}（随机端口，绝不联网）；
 * 直接构造实现（不依赖 {@code IdentityEnrollmentConfig} 的 profile 装配，
 * 装配矩阵由 {@code IdentityEnrollmentConfigTest} 单独锁定）。</p>
 */
class IdentityEnrollmentIT extends AbstractWebIT {

    private static final String NS = "mvp-ns-1";
    private static final String FAKE_TOKEN = "FAKE-INTERNAL-TOKEN-DO-NOT-USE";

    private static final Set<String> ENROLLMENT_KEYS = Set.of(
            "correlation_id", "provider_request_id", "provider_config_revision", "registered_at",
            "source_assessment_id", "photo_version", "processing_revision", "phase",
            "candidate_entity_id", "policy_version", "model_version", "library_revision");

    @Autowired
    JdbcTemplate jdbc;

    @Autowired
    TransactionTemplate txTemplate;

    @Autowired
    MediaService mediaService;

    @Autowired
    StoragePort storagePort;

    @Autowired
    AppProperties appProperties;

    private FaceServiceStub stub;

    @BeforeEach
    void startStub() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
    }

    @AfterEach
    void stopStub() {
        stub.close();
    }

    // ------------------------------------------------------------------ seeds / helpers

    private record Scenario(UUID assessmentId, String faceSubjectRef,
                            IdentityEnrollmentCommand command,
                            UUID front, UUID left, UUID right, byte[] frontBytes) {
    }

    private UUID seedGimbal() {
        UUID id = UUID.randomUUID();
        jdbc.update("INSERT INTO gimbals (id, serial_no, auth_subject_ref, credential_version)"
                + " VALUES (?, ?, ?, 1)", id, "SN-ENROLL-" + id, "authref-" + id);
        return id;
    }

    private UUID seedIdempotencyRequest() {
        UUID id = UUID.randomUUID();
        jdbc.update("INSERT INTO idempotency_requests (id, principal_type, principal_id, operation,"
                        + " idempotency_key, payload_hash, status)"
                        + " VALUES (?, 'test', 'seed', 'test.enrollment', ?, 'seed', 'succeeded')",
                id, "k-" + id);
        return id;
    }

    private static String pendingJson(String candidateEntityId, String correlationId, String phase) {
        return "{\"schema_version\":1,\"classification\":\"reliable_new\","
                + "\"candidate_entity_id\":\"" + candidateEntityId + "\","
                + "\"phase\":\"" + phase + "\",\"correlation_id\":\"" + correlationId + "\"}";
    }

    private UUID seedAssessment(UUID gimbalId, long photoVersion, long processingRevision,
                                String identityResultJson) {
        UUID id = UUID.randomUUID();
        jdbc.update("INSERT INTO skin_assessments (id, gimbal_id, status, current_photo_version,"
                        + " processing_revision, identity_result, source_request_id)"
                        + " VALUES (?, ?, 'analyzing', ?, ?, CAST(? AS jsonb), ?)",
                id, gimbalId, photoVersion, processingRevision, identityResultJson,
                seedIdempotencyRequest());
        return id;
    }

    private UUID seedMedia(byte[] bytes) {
        UUID id = UUID.randomUUID();
        String key = appProperties.env() + "/assessment_source/" + id;
        storagePort.put(key, new ByteArrayInputStream(bytes), bytes.length, "image/png");
        jdbc.update("INSERT INTO media_objects (id, bucket, object_key, purpose, state,"
                        + " content_type, byte_size)"
                        + " VALUES (?, ?, ?, 'assessment_source', 'available', 'image/png', ?)",
                id, appProperties.storage().bucket(), key, bytes.length);
        return id;
    }

    private Scenario seedScenario(long photoVersion, long processingRevision) {
        UUID gimbalId = seedGimbal();
        UUID assessmentId = UUID.randomUUID();
        String ref = IdentityResultContract.candidateEntityId(NS, assessmentId);
        String correlationId = IdentityResultContract.enrollCorrelationId(NS, assessmentId);
        String requestId = IdentityResultContract.providerRequestId(correlationId);
        seedAssessment(gimbalId, photoVersion, processingRevision,
                pendingJson(ref, correlationId, "enroll_pending"));

        byte[] frontBytes = png(1);
        UUID front = seedMedia(frontBytes);
        UUID left = seedMedia(png(2));
        UUID right = seedMedia(png(3));

        IdentityEnrollmentCommand command = new IdentityEnrollmentCommand(NS, assessmentId,
                processingRevision, photoVersion, front.toString(), left.toString(), right.toString(),
                correlationId, requestId, "cfg-rev-1", "search-v1", "buffalo_l@fake", 12L, "no_match");
        return new Scenario(assessmentId, ref, command, front, left, right, frontBytes);
    }

    private static byte[] png(int marker) {
        return new byte[]{(byte) 0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A,
                (byte) marker, (byte) (marker >> 8), 'D', 'A', 'T', 'A'};
    }

    private static String registerBody(String ref) {
        return "{\"subject_id\":\"" + ref + "\",\"namespace\":\"" + NS + "\",\"created\":true,"
                + "\"created_at\":\"2026-09-16T04:05:06Z\",\"library_revision\":4,"
                + "\"request_id\":\"r-reg\"}";
    }

    private static String getBody(String ref) {
        return "{\"subject_id\":\"" + ref + "\",\"created_at\":\"2026-09-16T04:05:06Z\","
                + "\"library_revision\":4,\"request_id\":\"r-get\"}";
    }

    private FaceServiceClient client(int readTimeoutMillis) {
        return new FaceServiceClient(new InsightFaceProperties(stub.baseUrl(), NS, FAKE_TOKEN, null,
                1000, readTimeoutMillis, 0.4), new ObjectMapper());
    }

    private IdentityEnrollmentService service() {
        return new JdbcIdentityEnrollmentService(jdbc, txTemplate, mediaService, client(1500));
    }

    private int countMembers(String faceSubjectRef) {
