import static org.mockito.Mockito.mock;

/**
 * {@link IdentityEnrollmentConfig} 装配矩阵（{@link ApplicationContextRunner}，不启动 web/PG、
 * 不访问真实人脸服务）：
 * <ul>
 *   <li>{@code insightface} + 非生产 ⇒ 装配 {@link JdbcIdentityEnrollmentService}；</li>
 *   <li>{@code doubles}（缺省）⇒ 不装配；</li>
 *   <li>{@code app.providers.mode=disabled} 优先于 {@code insightface} ⇒ 不装配；</li>
 *   <li>生产信号 ⇒ 不装配（与 {@code InsightFaceCareVerifier} 的生产处置一致）。</li>
 * </ul>
 */
class IdentityEnrollmentConfigTest {

    @Configuration
    @EnableConfigurationProperties({AppProperties.class, InsightFaceProperties.class,
            AliyunFaceProperties.class})
    static class DepsConfig {
        @Bean
        JdbcTemplate jdbcTemplate() {
            return mock(JdbcTemplate.class);
        }

        @Bean
        TransactionTemplate transactionTemplate() {
            return mock(TransactionTemplate.class);
        }

        @Bean
        MediaService mediaService() {
            return mock(MediaService.class);
        }

        @Bean
        ObjectMapper objectMapper() {
            return new ObjectMapper();
        }
    }

    private static ApplicationContextRunner runner(String... profiles) {
        return new ApplicationContextRunner()
                .withUserConfiguration(DepsConfig.class, FaceProvidersConfig.class,
                        IdentityEnrollmentConfig.class, AliyunFaceBoundaryConfig.class)
                .withInitializer(ctx -> ctx.getEnvironment().setActiveProfiles(profiles));
    }

    private static String[] insightface() {
        return new String[]{
                "app.face.provider=insightface",
                "app.face.insightface.base-url=http://10.3.6.163:8010",
                "app.face.insightface.namespace=mvp-ns-1",
                "app.face.insightface.internal-token=FAKE-INTERNAL-TOKEN-DO-NOT-USE"};
    }

    @Test
    @DisplayName("provider=insightface（非生产）⇒ 装配 JdbcIdentityEnrollmentService")
    void insightfaceAssemblesEnrollmentService() {
        runner("local").withPropertyValues("app.env=dev").withPropertyValues(insightface())
                .run(ctx -> {
                    assertThat(ctx).hasNotFailed();
                    assertInstanceOf(JdbcIdentityEnrollmentService.class,
                            ctx.getBean(IdentityEnrollmentService.class));
                });
    }

    @Test
    @DisplayName("provider=doubles（缺省）⇒ 不装配（身份登记仅在有真实人脸端口时可用）")
    void doublesModeDoesNotAssembleEnrollmentService() {
        runner("local").withPropertyValues("app.env=dev").run(ctx -> {
            assertThat(ctx).hasNotFailed();
            assertThat(ctx.getBeansOfType(IdentityEnrollmentService.class)).isEmpty();
        });
    }

    @Test
    @DisplayName("mode=disabled + provider=insightface ⇒ disabled 优先，不装配")
    void disabledModeWinsOverInsightface() {
        runner("local").withPropertyValues("app.env=dev", "app.providers.mode=disabled")
                .withPropertyValues(insightface())
                .run(ctx -> {
                    assertThat(ctx).hasNotFailed();
                    assertThat(ctx.getBeansOfType(IdentityEnrollmentService.class)).isEmpty();
                });
    }

    @Test
    @DisplayName("生产信号（prod profile）+ provider=insightface ⇒ 不装配")
    void productionSignalDoesNotAssembleEnrollmentService() {
        runner("prod").withPropertyValues("app.env=dev").withPropertyValues(insightface())
                .run(ctx -> {
                    assertThat(ctx).hasNotFailed();
                    assertThat(ctx.getBeansOfType(IdentityEnrollmentService.class)).isEmpty();
                });
    }
}

